// Stripe sends the subscription, and the customer arrives from the node before this one.
const ev = $json.body || $json;
const sub = (ev.data && ev.data.object) || ev.object || ev;

let customer = {};
try { customer = $('Look up the customer').first().json || {}; } catch (e) {}

const price = ((sub.items && sub.items.data && sub.items.data[0]) || {}).price || {};
const minor = Number(price.unit_amount || 0);
const currency = String(price.currency || 'usd').toUpperCase();
const zeroDecimal = ['JPY','KRW','VND','CLP','ISK','UGX','XAF','XOF','BIF','DJF','GNF','KMF','MGA','PYG','RWF','VUV','XPF'];
const amount = zeroDecimal.includes(currency) ? minor : minor / 100;

const started = Number(sub.start_date || sub.created || 0) * 1000;
const tenureDays = started ? Math.max(0, Math.floor((Date.now() - started) / 86400000)) : null;

// Stripe captures a reason itself when the customer cancels through the billing portal.
// When it did, there is nothing to ask and sending a survey would be irritating.
const cd = sub.cancellation_details || {};
const feedbackMap = {
  too_expensive: 'Too expensive',
  missing_features: 'Missing a feature I needed',
  switched_service: 'Switched to something else',
  unused: 'No longer need it',
  too_complex: 'It was harder to use than expected',
  low_quality: 'Quality was not good enough',
  customer_service: 'Customer service',
  other: 'Something else',
};
const stripeReason = [feedbackMap[cd.feedback] || '', String(cd.comment || '')].filter(Boolean).join('. ');

return [{ json: {
  source: 'stripe',
  email: String(customer.email || sub.customer_email || '').trim(),
  name: String(customer.name || '').trim(),
  customerId: typeof sub.customer === 'string' ? sub.customer : ((sub.customer && sub.customer.id) || ''),
  subscriptionId: sub.id || '',
  plan: (price.nickname || (price.recurring && price.recurring.interval) || 'unknown'),
  amount,
  currency,
  mrr: (price.recurring && price.recurring.interval === 'year') ? Math.round((amount / 12) * 100) / 100 : amount,
  tenureDays,
  cancelledAt: new Date().toISOString().slice(0, 10),
  reasonText: stripeReason,
  hasReason: !!stripeReason,
} }];

// The same record shape, built from the form answers instead.
const raw = $json;
const pick = (...labels) => {
  for (const l of labels) {
    for (const k of Object.keys(raw)) {
      if (k.toLowerCase().trim() === l.toLowerCase()) {
        const v = raw[k];
        if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
      }
    }
  }
  return '';
};

const choice = pick('What made you cancel');
const detail = pick('Anything you want to add');

return [{ json: {
  source: 'survey',
  email: pick('Your email'),
  name: '',
  customerId: '',
  subscriptionId: '',
  plan: 'unknown',
  amount: null,
  currency: '',
  mrr: null,
  tenureDays: null,
  cancelledAt: new Date().toISOString().slice(0, 10),
  reasonText: [choice, detail].filter(Boolean).join('. '),
  hasReason: !!(choice || detail),
} }];

const cfg = $('Set config: brand, survey link and recipient').first().json;
const r = $json;
const hi = r.name ? 'Hi ' + r.name.split(' ')[0] + ',' : 'Hi,';

const body = [
  hi,
  '',
  'Your ' + cfg.brandName + ' subscription has been cancelled, and that is all done. Nothing else to do.',
  '',
  'One question, if you have ten seconds: what made you cancel? It is a single click and it genuinely changes what we build next.',
  '',
  cfg.surveyUrl,
  '',
  'Thanks either way,',
  cfg.fromName,
].join('\n');

return [{ json: { ...r, askSubject: 'One question about your cancellation', askBody: body } }];

const cfg = $('Set config: brand, survey link and recipient').first().json;
const r = $json;
const categories = ['too_expensive','missing_feature','switched_to_competitor','no_longer_needed','too_hard_to_use','temporary_need','service_quality','other'];
const schema = { type: 'object', additionalProperties: false,
  required: ['category','preventable','save_worth_trying','summary','suggested_action'], properties: {
    category: { type: 'string', enum: categories },
    preventable: { type: 'boolean' },
    save_worth_trying: { type: 'boolean' },
    summary: { type: 'string' },
    suggested_action: { type: 'string' } } };

const system = 'You categorise cancellation reasons for ' + cfg.brandName + '. Work only from what the ' +
  'customer actually said. Never infer a reason they did not give: if the text is empty or says nothing ' +
  'useful, use category other and say so in the summary. preventable is true only when the company could ' +
  'plausibly have changed the outcome, so pricing, missing features and usability are preventable while ' +
  'a genuinely temporary need or a business closing is not. save_worth_trying is about whether a human ' +
  'reaching out now is likely to help, not about how much the account was worth. suggested_action is one ' +
  'concrete sentence aimed at the company, not at the customer. Keep summary under 25 words. ' +
  'Do not use em dashes.';

const user = [
  'WHAT THEY SAID: ' + (r.reasonText || '(nothing)'),
  'HOW WE GOT IT: ' + (r.source === 'stripe' ? 'Stripe billing portal at cancellation' : 'exit survey reply'),
  r.plan && r.plan !== 'unknown' ? 'PLAN: ' + r.plan : '',
  r.mrr ? 'MONTHLY VALUE: ' + r.mrr + ' ' + r.currency : '',
  r.tenureDays !== null && r.tenureDays !== undefined ? 'THEY WERE A CUSTOMER FOR ' + r.tenureDays + ' DAYS' : '',
].filter(Boolean).join('\n');

return [{ json: { body: {
  model: cfg.model, max_tokens: 700, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

// The config node runs with includeOtherFields, so its output carries the churn record too.
// Reading both from one place means this node does not care which trigger fired.
const cfg = $('Set config: brand, survey link and recipient').first().json;
const r = cfg;
const blocks = ($json.content || []);
const text = (blocks.find((b) => b.type === 'text') || {}).text || '{}';

let a = {};
try { a = JSON.parse(text) || {}; } catch (e) {}

const category = a.category || 'other';
const pretty = category.replace(/_/g, ' ');

// Never lose the churn record because the model misbehaved.
const summary = a.summary || (r.reasonText ? r.reasonText.slice(0, 140) : 'No reason was given.');

const flag = a.save_worth_trying ? 'WORTH A REPLY' : (a.preventable ? 'PREVENTABLE' : 'FYI');
const subject = '[' + flag + '] Cancelled: ' + pretty + (r.email ? ' (' + r.email + ')' : '');

const body = [
  summary,
  '',
  'WHAT THEY SAID',
  '  ' + (r.reasonText || '(nothing given)'),
  '',
  'THE ACCOUNT',
  '  Customer:  ' + (r.name || r.email || 'unknown'),
  r.mrr ? '  Value:     ' + r.mrr + ' ' + r.currency + ' per month' : '',
  r.tenureDays !== null && r.tenureDays !== undefined ? '  Tenure:    ' + r.tenureDays + ' days' : '',
  '  Source:    ' + (r.source === 'stripe' ? 'Stripe billing portal' : 'exit survey'),
  '',
  'READ',
  '  Category:    ' + pretty,
  '  Preventable: ' + (a.preventable ? 'yes' : 'no'),
  a.suggested_action ? '  Do this:     ' + a.suggested_action : '',
].filter((l) => l !== '').join('\n');

return [{ json: {
  subject, body,
  notifyTo: cfg.notifyTo,
  date: r.cancelledAt,
  email: r.email,
  plan: r.plan,
  mrr: r.mrr,
  tenure_days: r.tenureDays,
  category,
  preventable: !!a.preventable,
  save_worth_trying: !!a.save_worth_trying,
  reason_text: r.reasonText,
  suggested_action: a.suggested_action || '',
} }];
